  final String eventType;
  final String? subjectType;
  final String? subjectId;
  final String? payloadJson;
  final Uint8List? previousEventHash;
  final Uint8List eventHash;
  final int createdAt;
  const GraphAuditEvent({
    required this.id,
    required this.eventType,
    this.subjectType,
    this.subjectId,
    this.payloadJson,
    this.previousEventHash,
    required this.eventHash,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['event_type'] = Variable<String>(eventType);
    if (!nullToAbsent || subjectType != null) {
      map['subject_type'] = Variable<String>(subjectType);
    }
    if (!nullToAbsent || subjectId != null) {
      map['subject_id'] = Variable<String>(subjectId);
    }
    if (!nullToAbsent || payloadJson != null) {
      map['payload_json'] = Variable<String>(payloadJson);
    }
    if (!nullToAbsent || previousEventHash != null) {
      map['previous_event_hash'] = Variable<Uint8List>(previousEventHash);
    }
    map['event_hash'] = Variable<Uint8List>(eventHash);
    map['created_at'] = Variable<int>(createdAt);
    return map;
  }

  GraphAuditEventsCompanion toCompanion(bool nullToAbsent) {
    return GraphAuditEventsCompanion(
      id: Value(id),
      eventType: Value(eventType),
      subjectType: subjectType == null && nullToAbsent
          ? const Value.absent()
          : Value(subjectType),
      subjectId: subjectId == null && nullToAbsent
          ? const Value.absent()
          : Value(subjectId),
      payloadJson: payloadJson == null && nullToAbsent
          ? const Value.absent()
          : Value(payloadJson),
      previousEventHash: previousEventHash == null && nullToAbsent
          ? const Value.absent()
          : Value(previousEventHash),
      eventHash: Value(eventHash),
      createdAt: Value(createdAt),
    );
  }

  factory GraphAuditEvent.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return GraphAuditEvent(
      id: serializer.fromJson<String>(json['id']),
      eventType: serializer.fromJson<String>(json['event_type']),
      subjectType: serializer.fromJson<String?>(json['subject_type']),
      subjectId: serializer.fromJson<String?>(json['subject_id']),
      payloadJson: serializer.fromJson<String?>(json['payload_json']),
      previousEventHash: serializer.fromJson<Uint8List?>(
        json['previous_event_hash'],
      ),
      eventHash: serializer.fromJson<Uint8List>(json['event_hash']),
      createdAt: serializer.fromJson<int>(json['created_at']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'event_type': serializer.toJson<String>(eventType),
      'subject_type': serializer.toJson<String?>(subjectType),
      'subject_id': serializer.toJson<String?>(subjectId),
      'payload_json': serializer.toJson<String?>(payloadJson),
      'previous_event_hash': serializer.toJson<Uint8List?>(previousEventHash),
      'event_hash': serializer.toJson<Uint8List>(eventHash),
      'created_at': serializer.toJson<int>(createdAt),
    };
  }

  GraphAuditEvent copyWith({
    String? id,
    String? eventType,
    Value<String?> subjectType = const Value.absent(),
    Value<String?> subjectId = const Value.absent(),
    Value<String?> payloadJson = const Value.absent(),
    Value<Uint8List?> previousEventHash = const Value.absent(),
    Uint8List? eventHash,
    int? createdAt,
  }) => GraphAuditEvent(
    id: id ?? this.id,
    eventType: eventType ?? this.eventType,
    subjectType: subjectType.present ? subjectType.value : this.subjectType,
    subjectId: subjectId.present ? subjectId.value : this.subjectId,
    payloadJson: payloadJson.present ? payloadJson.value : this.payloadJson,
    previousEventHash: previousEventHash.present
        ? previousEventHash.value
        : this.previousEventHash,
    eventHash: eventHash ?? this.eventHash,
    createdAt: createdAt ?? this.createdAt,
  );
  GraphAuditEvent copyWithCompanion(GraphAuditEventsCompanion data) {
    return GraphAuditEvent(
      id: data.id.present ? data.id.value : this.id,
      eventType: data.eventType.present ? data.eventType.value : this.eventType,
      subjectType: data.subjectType.present
          ? data.subjectType.value
          : this.subjectType,
      subjectId: data.subjectId.present ? data.subjectId.value : this.subjectId,
      payloadJson: data.payloadJson.present
          ? data.payloadJson.value
          : this.payloadJson,
      previousEventHash: data.previousEventHash.present
          ? data.previousEventHash.value
          : this.previousEventHash,
      eventHash: data.eventHash.present ? data.eventHash.value : this.eventHash,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('GraphAuditEvent(')
          ..write('id: $id, ')
          ..write('eventType: $eventType, ')
          ..write('subjectType: $subjectType, ')
          ..write('subjectId: $subjectId, ')
          ..write('payloadJson: $payloadJson, ')
          ..write('previousEventHash: $previousEventHash, ')
          ..write('eventHash: $eventHash, ')
          ..write('createdAt: $createdAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    eventType,
    subjectType,
    subjectId,
    payloadJson,
    $driftBlobEquality.hash(previousEventHash),
    $driftBlobEquality.hash(eventHash),
    createdAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is GraphAuditEvent &&
          other.id == this.id &&
          other.eventType == this.eventType &&
          other.subjectType == this.subjectType &&
          other.subjectId == this.subjectId &&
          other.payloadJson == this.payloadJson &&
          $driftBlobEquality.equals(
            other.previousEventHash,
            this.previousEventHash,
          ) &&
          $driftBlobEquality.equals(other.eventHash, this.eventHash) &&
          other.createdAt == this.createdAt);
}

class GraphAuditEventsCompanion extends UpdateCompanion<GraphAuditEvent> {
  final Value<String> id;
  final Value<String> eventType;
  final Value<String?> subjectType;
  final Value<String?> subjectId;
  final Value<String?> payloadJson;
  final Value<Uint8List?> previousEventHash;
  final Value<Uint8List> eventHash;
  final Value<int> createdAt;
  final Value<int> rowid;
  const GraphAuditEventsCompanion({
    this.id = const Value.absent(),
    this.eventType = const Value.absent(),
    this.subjectType = const Value.absent(),
    this.subjectId = const Value.absent(),
    this.payloadJson = const Value.absent(),
    this.previousEventHash = const Value.absent(),
    this.eventHash = const Value.absent(),
    this.createdAt = const Value.absent(),
    this.rowid = const Value.absent(),
  });
  GraphAuditEventsCompanion.insert({
    required String id,
    required String eventType,
    this.subjectType = const Value.absent(),
    this.subjectId = const Value.absent(),
    this.payloadJson = const Value.absent(),
    this.previousEventHash = const Value.absent(),
    required Uint8List eventHash,
    required int createdAt,
    this.rowid = const Value.absent(),
  }) : id = Value(id),
       eventType = Value(eventType),
       eventHash = Value(eventHash),
       createdAt = Value(createdAt);
  static Insertable<GraphAuditEvent> custom({
    Expression<String>? id,
    Expression<String>? eventType,
    Expression<String>? subjectType,
    Expression<String>? subjectId,
    Expression<String>? payloadJson,
    Expression<Uint8List>? previousEventHash,
    Expression<Uint8List>? eventHash,
    Expression<int>? createdAt,
    Expression<int>? rowid,
  }) {
    return RawValuesInsertable({
      if (id != null) 'id': id,
      if (eventType != null) 'event_type': eventType,
      if (subjectType != null) 'subject_type': subjectType,
      if (subjectId != null) 'subject_id': subjectId,
      if (payloadJson != null) 'payload_json': payloadJson,
      if (previousEventHash != null) 'previous_event_hash': previousEventHash,
      if (eventHash != null) 'event_hash': eventHash,
      if (createdAt != null) 'created_at': createdAt,
      if (rowid != null) 'rowid': rowid,
    });
  }

  GraphAuditEventsCompanion copyWith({
    Value<String>? id,
    Value<String>? eventType,
    Value<String?>? subjectType,
    Value<String?>? subjectId,
    Value<String?>? payloadJson,
    Value<Uint8List?>? previousEventHash,
    Value<Uint8List>? eventHash,
    Value<int>? createdAt,
    Value<int>? rowid,
  }) {
    return GraphAuditEventsCompanion(
      id: id ?? this.id,
      eventType: eventType ?? this.eventType,
      subjectType: subjectType ?? this.subjectType,
      subjectId: subjectId ?? this.subjectId,
      payloadJson: payloadJson ?? this.payloadJson,
      previousEventHash: previousEventHash ?? this.previousEventHash,
      eventHash: eventHash ?? this.eventHash,
      createdAt: createdAt ?? this.createdAt,
      rowid: rowid ?? this.rowid,
    );
  }

  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (id.present) {
      map['id'] = Variable<String>(id.value);
    }
    if (eventType.present) {
      map['event_type'] = Variable<String>(eventType.value);
    }
    if (subjectType.present) {
      map['subject_type'] = Variable<String>(subjectType.value);
    }
    if (subjectId.present) {
      map['subject_id'] = Variable<String>(subjectId.value);
    }
    if (payloadJson.present) {
      map['payload_json'] = Variable<String>(payloadJson.value);
    }
    if (previousEventHash.present) {
      map['previous_event_hash'] = Variable<Uint8List>(previousEventHash.value);
    }
    if (eventHash.present) {
      map['event_hash'] = Variable<Uint8List>(eventHash.value);
    }
    if (createdAt.present) {
      map['created_at'] = Variable<int>(createdAt.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('GraphAuditEventsCompanion(')
          ..write('id: $id, ')
          ..write('eventType: $eventType, ')
          ..write('subjectType: $subjectType, ')
          ..write('subjectId: $subjectId, ')
          ..write('payloadJson: $payloadJson, ')
          ..write('previousEventHash: $previousEventHash, ')
          ..write('eventHash: $eventHash, ')
          ..write('createdAt: $createdAt, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

