class $EntitiesTableManager
    extends
        RootTableManager<
          _$CitizenVaultDatabase,
          Entities,
          Entity,
          $EntitiesFilterComposer,
          $EntitiesOrderingComposer,
          $EntitiesAnnotationComposer,
          $EntitiesCreateCompanionBuilder,
          $EntitiesUpdateCompanionBuilder,
          (Entity, $EntitiesReferences),
          Entity,
          PrefetchHooks Function({
            bool claimsRefs,
            bool claimValuesRefs,
            bool lifeEventsRefs,
            bool eventEntitiesRefs,
            bool derivedStatesRefs,
            bool attentionItemsRefs,
            bool lifeTasksRefs,
            bool lifeChecklistsRefs,
            bool smartPacksRefs,
          })
        > {
  $EntitiesTableManager(_$CitizenVaultDatabase db, Entities table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $EntitiesFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $EntitiesOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $EntitiesAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String> entityType = const Value.absent(),
                Value<String?> subtype = const Value.absent(),
                Value<String> displayName = const Value.absent(),
                Value<String> status = const Value.absent(),
                Value<int> createdAt = const Value.absent(),
                Value<int> updatedAt = const Value.absent(),
                Value<int?> archivedAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => EntitiesCompanion(
                id: id,
                entityType: entityType,
                subtype: subtype,
                displayName: displayName,
                status: status,
                createdAt: createdAt,
                updatedAt: updatedAt,
                archivedAt: archivedAt,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                required String entityType,
                Value<String?> subtype = const Value.absent(),
                required String displayName,
                Value<String> status = const Value.absent(),
                required int createdAt,
                required int updatedAt,
                Value<int?> archivedAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => EntitiesCompanion.insert(
                id: id,
                entityType: entityType,
                subtype: subtype,
                displayName: displayName,
                status: status,
                createdAt: createdAt,
                updatedAt: updatedAt,
                archivedAt: archivedAt,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (e.readTable(table), $EntitiesReferences(db, table, e)),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                claimsRefs = false,
                claimValuesRefs = false,
                lifeEventsRefs = false,
                eventEntitiesRefs = false,
                derivedStatesRefs = false,
                attentionItemsRefs = false,
                lifeTasksRefs = false,
                lifeChecklistsRefs = false,
                smartPacksRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (claimsRefs) db.claims,
                    if (claimValuesRefs) db.claimValues,
                    if (lifeEventsRefs) db.lifeEvents,
                    if (eventEntitiesRefs) db.eventEntities,
                    if (derivedStatesRefs) db.derivedStates,
                    if (attentionItemsRefs) db.attentionItems,
                    if (lifeTasksRefs) db.lifeTasks,
                    if (lifeChecklistsRefs) db.lifeChecklists,
                    if (smartPacksRefs) db.smartPacks,
                  ],
                  addJoins: null,
                  getPrefetchedDataCallback: (items) async {
                    return [
                      if (claimsRefs)
                        await $_getPrefetchedData<Entity, Entities, Claim>(
                          currentTable: table,
                          referencedTable: $EntitiesReferences._claimsRefsTable(
                            db,
                          ),
                          managerFromTypedResult: (p0) =>
                              $EntitiesReferences(db, table, p0).claimsRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.subjectEntityId == item.id,
                              ),
                          typedResults: items,
                        ),
                      if (claimValuesRefs)
                        await $_getPrefetchedData<Entity, Entities, ClaimValue>(
                          currentTable: table,
                          referencedTable: $EntitiesReferences
                              ._claimValuesRefsTable(db),
                          managerFromTypedResult: (p0) => $EntitiesReferences(
                            db,
                            table,
                            p0,
                          ).claimValuesRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.entityReferenceId == item.id,
                              ),
                          typedResults: items,
                        ),
                      if (lifeEventsRefs)
                        await $_getPrefetchedData<Entity, Entities, LifeEvent>(
                          currentTable: table,
                          referencedTable: $EntitiesReferences
                              ._lifeEventsRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $EntitiesReferences(db, table, p0).lifeEventsRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.locationEntityId == item.id,
                              ),
                          typedResults: items,
                        ),
                      if (eventEntitiesRefs)
                        await $_getPrefetchedData<
                          Entity,
                          Entities,
                          EventEntity
                        >(
                          currentTable: table,
                          referencedTable: $EntitiesReferences
                              ._eventEntitiesRefsTable(db),
