final class $RelationshipHistoryReferences
    extends
        BaseReferences<
          _$CitizenVaultDatabase,
          RelationshipHistory,
          RelationshipHistoryData
        > {
  $RelationshipHistoryReferences(
    super.$_db,
    super.$_table,
    super.$_typedResult,
  );

  static Relationships _relationshipIdTable(_$CitizenVaultDatabase db) =>
      db.relationships.createAlias(
        $_aliasNameGenerator(
          db.relationshipHistory.relationshipId,
          db.relationships.id,
        ),
      );

  $RelationshipsProcessedTableManager get relationshipId {
    final $_column = $_itemColumn<String>('relationship_id')!;

    final manager = $RelationshipsTableManager(
      $_db,
      $_db.relationships,
    ).filter((f) => f.id.sqlEquals($_column));
    final item = $_typedResult.readTableOrNull(_relationshipIdTable($_db));
    if (item == null) return manager;
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: [item]),
    );
  }

  static ProvenanceRecords _provenanceIdTable(_$CitizenVaultDatabase db) =>
      db.provenanceRecords.createAlias(
        $_aliasNameGenerator(
          db.relationshipHistory.provenanceId,
          db.provenanceRecords.id,
        ),
      );

  $ProvenanceRecordsProcessedTableManager? get provenanceId {
    final $_column = $_itemColumn<String>('provenance_id');
    if ($_column == null) return null;
    final manager = $ProvenanceRecordsTableManager(
      $_db,
      $_db.provenanceRecords,
    ).filter((f) => f.id.sqlEquals($_column));
    final item = $_typedResult.readTableOrNull(_provenanceIdTable($_db));
    if (item == null) return manager;
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: [item]),
    );
  }
}

